    _rules = [{"event": 205, "p1": None, "answer": "", "set": "128=99", "note": "n"},
              {"event": 205, "p1": 34, "answer": "p1=flag[p3];p2=0", "set": "p3=99;173", "note": "x"},
              {"event": 104, "p1": None, "answer": "p1=flag[p1]", "set": "", "note": "q"}]
    _r = event_rule_for(205, _ps, _rules)
    _fl0 = bytes(256)
    _ans, _nfl, _what = apply_event_rule(_r, _ps, _fl0)
    _ans2, _nfl2, _what2 = apply_event_rule(_rules[2], [130] + [0] * 15, _nfl)
    _again = apply_event_rule(_r, _ps, _nfl)            # idempotent: nothing to change
    _out = answered_0159(bytes(_rec), _ans)
