    _b2 = objective_tick(_hst, _PosChan((15.0, 0.0, 15.0, 0.0)), 1012.0, _hobj)  # 29s left -> "30s"
    _b3 = objective_tick(_hst, _PosChan((99.0, 0.0, 15.0, 0.0)), 1020.0, _hobj)  # left the zone
    _b4 = objective_tick(_hst, _PosChan((15.0, 0.0, 15.0, 0.0)), 1030.0, _hobj)  # re-entered
    _b5 = objective_tick(_hst, _PosChan((15.0, 0.0, 15.0, 0.0)), 1071.0, _hobj)  # 41s held
    _b6 = objective_tick(_hst, _PosChan((15.0, 0.0, 15.0, 0.0)), 1072.0, _hobj)  # done: quiet
